{
  "pass": false,
  "problems": [
    {
      "type": "中身のずれ",
      "where": "summary の hs",
      "detail": "stdにある「役所は不開示情報を除き開示する義務を負う」という重要な義務についての記述が抜けており、後半の情報（手数料や決定期間など）も要約しきれず欠けています。",
      "fix": "stdの意味に合わせて、国や市の役所が持っている文書をだれでも求めることができ、原則として見せる義務があることを盛り込むように直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/0/text の hs",
      "detail": "stdが「国の役所の文書を請求すると、いくらかかって、いつ結果がわかる？」という問いであるのに対し、hsは「国や市の役所が持っている書類を、見せてもらうことはできるのでしょうか？」となっており、問いの内容がずれています。",
      "fix": "stdの内容に合わせて、手数料や期間に関する疑問を含んだ問いに直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/0/text の hs",
      "detail": "stdは「何人も行政機関の長に対し行政文書の開示を請求できる（第3条）」という権利の主体と対象について述べていますが、hsは「見たい文書がある役所に、請求書を出します」という手順の説明になっており、内容がずれています。",
      "fix": "stdに合わせて、だれでも役所の長に文書の開示を求められるという内容に直す。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/1/text の hs",
      "detail": "stdにある「開示を受けるときは別に開示実施手数料がかかる」という内容が抜けています。",
      "fix": "見せてもらうとき別の手数料がかかるという点もhsに加える。"
    },
    {
      "type": "中身のずれ",
      "where": "blocks/1/items/3/text の hs",
      "detail": "stdにある「審査請求ができる」「審査会に諮問する」「取消訴訟を起こすこともできる」という不服申立ての具体的な仕組みが大幅に抜け落ちています。",
      "fix": "見直しを求めることができることや裁判のことにふれるように直す。"
    }
  ]
}
